import fs from 'node:fs';import path from 'node:path';import env from '@next/env';import {getPgPool} from '../server/database/pgClient.js';import {insertRecurringCharge} from '../server/features/prevision/RecurringChargeRepository.js';import {saveBankWorkflow} from '../server/features/banco/BankReviewWorkflow.js';import {syncJuanOperationalRows} from '../server/features/prevision/JuanOperationalSync.js';
env.loadEnvConfig(process.cwd());const pool=getPgPool(),connect=pool.connect.bind(pool),db=await connect(),folder=path.join(process.env.USERPROFILE,'Downloads/updates/revision-gastos-20261004/comparacion-2026');
try{await db.query('BEGIN');await db.query("SELECT pg_advisory_xact_lock(hashtext('laboral:pagos'))");const backup={};for(const t of ['tesoreria_cargos_recurrentes','tesoreria_cargos_vencimientos','tesoreria_movimientos_bancarios','tesoreria_prevision_juan','tesoreria_prevision_juan_enlaces','tesoreria_prevision_juan_asociaciones'])backup[t]=(await db.query('SELECT * FROM '+t)).rows;fs.writeFileSync(path.join(folder,'before-bitavis.json'),JSON.stringify(backup),{flag:'wx'});
pool.connect=async()=>({release(){},query:(sql,args)=>['BEGIN','COMMIT','ROLLBACK'].includes(sql)?Promise.resolve({rows:[],rowCount:0}):db.query(sql,args)});
const provider='prov_excel_bitavis_serveis_informatics';if((await db.query("SELECT 1 FROM tesoreria_cargos_recurrentes WHERE activo AND id_proveedor=$1 AND EXISTS(SELECT 1 FROM jsonb_array_elements(programacion) r WHERE r->>'descripcion' ILIKE '%MICROSOFT%')",[provider])).rowCount)throw Error('Annual Microsoft charge already exists; stop to avoid duplicate');
const charge=await insertRecurringCharge(db,{tipo_cargo:'proveedor',id_proveedor:provider,banco_pago:'Sabadell',tipo_programacion:'periodicidad',programacion:[{cada:12,unidad:'meses',inicio_dia:'2',inicio_mes:'2',inicio_anio:'2027',total_iva:1181.93,base_imponible:976.8,contains_iva:true,tipo_iva:21,descripcion:'BITAVIS · MICROSOFT 365 ANUAL',fecha_estimada:true,fecha_evidence:'Anual confirmado por el usuario. Próxima fecha estimada 02/02/2027 según factura A6667 de 02/02/2026; el pago previo fue 27/05/2026. Pendiente confirmar fecha de renovación.',fiscal_evidence:'Factura A6667: base 976,80 €, total 1.181,93 €.'}]});
const id='banc_sab_26_000.000.300',line=(await db.query('SELECT * FROM tesoreria_movimientos_bancarios WHERE id_linea_banco=$1',[id])).rows[0];await saveBankWorkflow({mode:'assign',ids:[id],items:[{id,version:line.updated_at,entityType:'proveedor',entityId:provider,chargeId:charge.id_cargo_recurrente,expectedSchedule:charge.programacion}]});
await db.query("UPDATE tesoreria_movimientos_bancarios SET comentarios=concat_ws(E'\\n',NULLIF(comentarios,''),$2::text),updated_at=now() WHERE id_linea_banco=$1",[id,'Microsoft 365 anual confirmado por el usuario. Separado de la cuota mensual Bitavis; no vuelve a preverse en octubre-diciembre 2026.']);
await db.query("UPDATE tesoreria_movimientos_bancarios SET comentarios=concat_ws(E'\\n',NULLIF(comentarios,''),$2::text),updated_at=now() WHERE id_linea_banco=$1",['banc_sab_26_000.000.102','Los 169,88 € adicionales fueron puntuales, confirmado por el usuario. No generan renovación.']);
await syncJuanOperationalRows(2027);const due=(await db.query("SELECT to_char(fecha,'YYYY-MM-DD') fecha,importe FROM tesoreria_cargos_vencimientos WHERE id_cargo_recurrente=$1 AND extract(year FROM fecha)=2027",[charge.id_cargo_recurrente])).rows;if(due.length!==1||Number(due[0].importe)!==1181.93)throw Error('Annual charge must occur exactly once in 2027');
pool.connect=connect;await db.query('COMMIT');const result={chargeId:charge.id_cargo_recurrente,dues:due,nextDateEstimated:true,oneOffExtra:169.88,unchanged2026Forecast:true};fs.writeFileSync(path.join(folder,'bitavis-annual.json'),JSON.stringify(result,null,2));console.log(JSON.stringify(result));
}catch(e){pool.connect=connect;await db.query('ROLLBACK');throw e;}finally{pool.connect=connect;db.release();await pool.end();}
